def simulate(products_info, daily_data, capacity, modify_day=None, modify_prod=None):
    # products_info: {p: {'weight': w, 'opening_stock': s}}
    # daily_data: {day: {p: {'produced': pr, 'ordered': or}}}

    stock = {p: info['opening_stock'] for p, info in products_info.items()}
    queue = [] # list of [product, quantity, day_placed, order_id]
    order_id_counter = 0
    results = {} # {day: {product: {stock, backordered}}}

    # Sort days
    days = sorted(daily_data.keys())

    for day in days:
        # 1. Production arrives
        for p in products_info:
            prod_qty = daily_data[day].get(p, {}).get('produced', 0)
            if modify_day == day and p == modify_prod:
                prod_qty = 0
            stock[p] += prod_qty

        # 2. Orders join the queue
        for p in products_info:
            ord_qty = daily_data[day].get(p, {}).get('ordered', 0)
            if ord_qty > 0:
                queue.append([p, ord_qty, day, order_id_counter])
                order_id_counter += 1

        # 3. Dispatch
        remaining_capacity = capacity

        # Sort queue: oldest first, then smaller remaining quantity, then lower product code
        # The queue is already mostly sorted by day_placed and order_id.
        # But the rule is: "among orders placed on the same day, the one with the smaller remaining quantity goes first, then the lower product code"
        # This means we need to re-sort or carefully pick.
        # Actually, "Open orders are served one at a time, oldest first" means we only look at the orders of the earliest day.
        # Within that day, we apply the tie-breakers.

        # To implement this correctly, we can process day by day.
        while queue:
            # Find the earliest day present in the queue
            earliest_day = min(item[2] for item in queue)
            # Get all orders from that day
            day_orders = [item for item in queue if item[2] == earliest_day]
            # Sort day_orders by quantity, then product code
            day_orders.sort(key=lambda x: (x[1], x[0]))

            # Pick the first order from the sorted list
            order = day_orders[0]
            p, qty, d, oid = order

            # How many can we ship?
            # Max based on stock
            can_ship_stock = stock[p]
            # Max based on capacity
            can_ship_cap = int(remaining_capacity // products_info[p]['weight'])

            shipped = min(qty, can_ship_stock, can_ship_cap)

            if shipped > 0:
                stock[p] -= shipped
                remaining_capacity -= shipped * products_info[p]['weight']
                # Update order in queue
                for item in queue:
                    if item[3] == oid:
                        item[1] -= shipped
                        break

            # If the order is fully shipped, remove it
            for item in queue:
                if item[3] == oid and item[1] == 0:
                    queue.remove(item)

